namespace SharpSlang.Native;

/// <summary>Severity of a diagnostic generated by the compiler. Values come from the enum below, with higher values representing more severe conditions, and all values &gt;= SLANG_SEVERITY_ERROR indicating compilation failure.</summary>
[NativeTypeName("SlangSeverityIntegral")]
public enum SlangSeverity
{
    /// <summary>A message that is disabled, filtered out.</summary>
    SLANG_SEVERITY_DISABLED = 0,
    /// <summary>An informative message.</summary>
    SLANG_SEVERITY_NOTE = 1,
    /// <summary>A warning, which indicates a possible problem.</summary>
    SLANG_SEVERITY_WARNING = 2,
    /// <summary>An error, indicating that compilation failed.</summary>
    SLANG_SEVERITY_ERROR = 3,
    /// <summary>An unrecoverable error, which forced compilation to abort.</summary>
    SLANG_SEVERITY_FATAL = 4,
    /// <summary>An internal error, indicating a logic error in the compiler.</summary>
    SLANG_SEVERITY_INTERNAL = 5,
}
